    /// `build.rs` refuses a catalogue where a `{{ name }}` is missing from
    /// one locale; its check ([`placeholder_mismatches`], the very file the
    /// build script includes) is exercised here, both ways.
    #[test]
    fn a_placeholder_missing_in_one_locale_is_a_mismatch() {
        let found = crate::placeholders::placeholder_mismatches(&[
            ("en", r#"{"k":"Hello {{ name }}"}"#),
            ("fr", r#"{"k":"Bonjour"}"#),
        ]);
        assert_eq!(found.len(), 1, "{found:?}");
        assert!(found[0].contains("\"k\""), "{found:?}");
        let same = crate::placeholders::placeholder_mismatches(&[
            ("en", r#"{"k":"Hello {{ name }}"}"#),
            ("fr", r#"{"k":"Bonjour {{ name }}"}"#),
        ]);
        assert_eq!(same.len(), 0, "{same:?}");
    }
